int lower_bound(int a[], int n, int x){
    int l = 0, r = n;
    while(l < r){
        int m = l + (r - l) / 2;
        if(a[m] < x) l = m + 1; else r = m;
    }
    return l;
}

int upper_bound(int a[], int n, int x){
    int l = 0, r = n;
    while(l < r){
        int m = l + (r - l) / 2;
        if(a[m] <= x) l = m + 1; else r = m;
    }
    return l;
}

int a[10] = {1,2,3,5,5,5,8,9,14,21}, n = 10;
lower_bound(a, n, 5);    // 3  (a[3] = 5, nho nhat >= 5)
upper_bound(a, n, 5);    // 6  (a[6] = 8, nho nhat > 5)
lower_bound(a, n, 22);   // 10 = n -> khong tim thay
